import React from 'react'
import { FaUser } from 'react-icons/fa'

const Navbar = () => {
  return (
    <nav className='w-full fixed'>
        <div className='w-full h-36 bg-white flex items-center justify-between px-10 shadow-md'>
            <div className='text-3xl font-bold ml-20  text-blue-600'>BookTime</div>
            <div>

                <div href="#" className='px-4 py-2 rounded-md mr-4 hover:text-purple-700'>
                    <FaUser />
                    Sign in</div>

                <div href="#" className='text-black px-4 py-2 rounded-md mr-30 hover:text-purple-700'>Sign Up</div>
            </div>

        </div>
    </nav>
  )
}

export default Navbar